from fastapi import FastAPI, Response, Depends
from fastapi.dependencies import analyze_param
from typing import Annotated
import inspect

def modify_response():
    return Response(content="modified")

app = FastAPI()

def test_annotated_response_depends():
    print("Testing Annotated[Response, Depends(modify_response)]")
    try:
        # Simulate how FastAPI calls analyze_param
        # In a real app, this happens during route initialization
        analyze_param(
            param_name="response",
            annotation=Annotated[Response, Depends(modify_response)],
            value=inspect.Signature.empty,
            is_path_param=False
        )
        print("Success!")
    except AssertionError as e:
        print(f"Failed with AssertionError: {e}")
    except Exception as e:
        print(f"Failed with {type(e).__name__}: {e}")

def test_response_depends_default():
    print("Testing response: Response = Depends(modify_response)")
    try:
        analyze_param(
            param_name="response",
            annotation=Response,
            value=Depends(modify_response),
            is_path_param=False
        )
        print("Success!")
    except AssertionError as e:
        print(f"Failed with AssertionError: {e}")
    except Exception as e:
        print(f"Failed with {type(e).__name__}: {e}")

def test_response_regular():
    print("Testing response: Response")
    try:
        analyze_param(
            param_name="response",
            annotation=Response,
            value=inspect.Signature.empty,
            is_path_param=False
        )
        print("Success!")
    except AssertionError as e:
        print(f"Failed with AssertionError: {e}")
    except Exception as e:
        print(f"Failed with {type(e).__name__}: {e}")

def test_response_invalid_field():
    print("Testing response: Response = Body(...) - should fail")
    from fastapi import Body
    try:
        analyze_param(
            param_name="response",
            annotation=Response,
            value=Body(...),
            is_path_param=False
        )
        print("Failed: Should have raised AssertionError")
    except AssertionError as e:
        print(f"Success: Raised AssertionError: {e}")
    except Exception as e:
        print(f"Failed with {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_annotated_response_depends()
    test_response_depends_default()
    test_response_regular()
    test_response_invalid_field()

